// validateAppACLR1FrozenSourceSnapshot makes the scoped r1 writer a
// closed-world consumer of the exact 0001...0051 source set. Generic migration
// discovery intentionally remains dynamic for legacy Apply.
func validateAppACLR1FrozenSourceSnapshot(snapshot migrationSourceSnapshot) error {
	expected := appACLR1MigrationSourceContract[:]
	if len(snapshot.names) != len(expected) || len(snapshot.sources) != len(expected) {
		return fmt.Errorf("frozen r1 migration source count is %d names/%d sources, want %d", len(snapshot.names), len(snapshot.sources), len(expected))
	}

	canonicalSet, err := CanonicalMigrationSetBodyV1(expected)
	if err != nil {
		return fmt.Errorf("build frozen r1 migration source canonical set: %w", err)
	}
	if !bytes.Equal(snapshot.canonicalSet, canonicalSet) {
		return fmt.Errorf("frozen r1 migration source canonical set does not match the r1 contract")
	}

	for index, expectedSource := range expected {
		if snapshot.names[index] != expectedSource.Filename {
			return fmt.Errorf("frozen r1 migration source at index %d is %q, want %q", index, snapshot.names[index], expectedSource.Filename)
		}
		source, ok := snapshot.sources[expectedSource.Filename]
		if !ok {
			return fmt.Errorf("frozen r1 migration source %q is missing", expectedSource.Filename)
		}
		if actualChecksum := sha256.Sum256([]byte(source.sql)); actualChecksum != expectedSource.Checksum {
			return fmt.Errorf("frozen r1 migration source %q has different SQL bytes", expectedSource.Filename)
		}
		if source.checksum != hexChecksum(expectedSource.Checksum) {
			return fmt.Errorf("frozen r1 migration source %q has different stored checksum", expectedSource.Filename)
		}
	}
	return nil
}

// validateAppACLR1FrozenSourcePrefix preserves the exact frozen R1 bytes while
// allowing the current-development contract to append explicit migrations.
func validateAppACLR1FrozenSourcePrefix(snapshot migrationSourceSnapshot) error {
	_, err := appACLR1FrozenSourcePrefix(snapshot)
	return err
}

func snapshotAppACLR1MigrationSources(fsys fs.FS) (migrationSourceSnapshot, error) {
	snapshot, err := snapshotMigrationSources(fsys)
	if err != nil {
		return migrationSourceSnapshot{}, err
	}
	return appACLR1FrozenSourcePrefix(snapshot)
}

func appACLR1FrozenSourcePrefix(snapshot migrationSourceSnapshot) (migrationSourceSnapshot, error) {
	prefixLength := len(appACLR1MigrationSourceContract)
	if len(snapshot.names) < prefixLength || len(snapshot.sources) < prefixLength {
		return migrationSourceSnapshot{}, fmt.Errorf("current migration source count is %d names/%d sources, want at least frozen r1 prefix length %d", len(snapshot.names), len(snapshot.sources), prefixLength)
	}

	prefix := migrationSourceSnapshot{
		sources: make(map[string]migrationSource, prefixLength),
		names:   append([]string(nil), snapshot.names[:prefixLength]...),
	}
	entries := make([]MigrationChecksumEntry, 0, prefixLength)
	for _, name := range prefix.names {
		source, ok := snapshot.sources[name]
		if !ok {
			return migrationSourceSnapshot{}, fmt.Errorf("current migration source prefix %q is missing", name)
		}
		prefix.sources[name] = source
		entries = append(entries, MigrationChecksumEntry{
			Filename: name,
			Checksum: sha256.Sum256([]byte(source.sql)),
		})
	}
	canonicalSet, err := CanonicalMigrationSetBodyV1(entries)
	if err != nil {
		return migrationSourceSnapshot{}, fmt.Errorf("build current migration source r1 prefix: %w", err)
	}
	prefix.canonicalSet = canonicalSet
	if err := validateAppACLR1FrozenSourceSnapshot(prefix); err != nil {
		return migrationSourceSnapshot{}, err
	}
	return prefix, nil
}
